    ActivityTips = "Activity_61369_ActivityTips|<Title:简介>\n黑池波云诡谲，命轮往复流转，在哈姆林的乐音牵引下，无限乐律齐奏，汇成你所跋涉的历程之命轮。愿它们的助力能陪伴你直至终末奏鸣的休止符。\n\n<Title:活动规则>\n·活动期间只需登录一天，即可在以下12个限定命轮中任选其一唤醒，包括：「神王的颂歌」、「至为珍贵的藏品」、「以蔷薇之名」、「跨越疼痛」、「隐秘的诞生」、「女王的戒律」、「神言石板」、「畸体回噬」、「虔诚的伟力」、「诗笺的句尾」、「慈悲的哺育」、「好运时间」。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1727398800,
    ActivityEndTime = 1733101200,
    ActivityPlot = "Activity_61369_ActivityPlot|守密人可以从以下限定命轮中任选其一唤醒！",
