    ActivityName = "Activity_48825_ActivityName|校猫的谢礼",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map60_small.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map60.png",
    ActivityTips = "Activity_48825_ActivityTips|<Title:简介>\n若非诸位的热切守望，弥萨格或许将永远埋没于漫长的黑夜。如今，我们已经践行了约定，一路走过坎坷，迎来了半周年纪念时刻。为此，校猫将为你献上一份特殊的礼物，感谢各位一直以来的陪伴。\n\n<Title:活动规则>\n·活动期间，每位守密人可以从8名限定SSR唤醒体中选择 1 名唤醒，包括图鲁、达芙黛尔、索蕾尔、莉莉、墨菲、旺达、萨尔瓦多、「24」。\n·当守密人选择已唤醒的唤醒体时，将会转换为对应唤醒体的残片×1和根源沉淀×50；若对应唤醒体的启灵等级已满，将转换为「灵核碎片」× 1和「根源沉淀」× 150。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1715994000,
    ActivityEndTime = 1721005200,
