    ActivityName = "Activity_116818_ActivityName|再战原初",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_WorldBoss1.png;UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_WorldBoss2.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map76.png;UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map77.png",
    ActivityTips = "Activity_116818_ActivityTips|<Title: 再战原初>\n·「再战原初」包含 7 个不可重现、直接挑战原初之视的关卡，活动前两天开放 1 个，第三天开放 3 个，之后两天每天开放 1 个。\n·每次挑战战胜对应的星辰原初之视后，即可获得对应奖励。\n·每种星辰原初之视均有大量分身，每当某个种类的星辰原初之视被任何守密人挑战胜利时，该类型的「残余数量」就会减少 1，当该类型星辰原初之视被消灭后，相应的关卡就会关闭，无法再次挑战。\n·每个关卡会提供不同的造物，将会为你提供强大的加成。\n·所有关卡必须选择助战，整个活动中，每个互相关注的守密人只能为你提供一次助战。由于使用助战，因此实际同调率奖励会在奖励基础上再提高 50%。\n·每天每个唤醒体、命轮、钥令只能出战 1 次。\n·活动期间特遣纪录「群星咏叹调」免费解锁开启且无需前置条件！玩法活动「再战原初」结束后，需要先完成「调查行动-星辰篇-第四章」才能开启特遣纪录「群星咏叹调」。\n\n<Title: 等级补偿>\n·在「再战原初」中有等级补偿机制，以便各位守密人能够并肩作战！\n等级补偿规则如下：\n  ·调查队伍中，等级不足 60 级的唤醒体在本次挑战中将会补偿至 60 级。\n  ·调查队伍中，技能等级不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n  ·调查队伍中，「疯狂预兆」不足 6 级的唤醒体在本次挑战中将会补偿至 6 级。\n  ·调查队伍中，「灵塑适性」不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n  ·若守密人等级不足60级，在本次挑战中将会补偿至60级。\n\n<Title:特遣纪录>\n·活动期间，「特遣纪录：群星咏叹调」可免费解锁开启且无需前置条件！\n·活动结束后，「特遣纪录：群星咏叹调」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「特遣纪录：群星咏叹调」，活动结束后需要先完成「调查行动-星辰篇-第四章」并消耗「现实起点」×7 才能开启特遣纪录「群星咏叹调」。\n·无论是否在活动期间，通关「特遣纪录：群星咏叹调」后都可以获得「钥令：重逢心愿」。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1764550800,
    ActivityEndTime = 1777597200,
    ActivityTimePara = {7, 116822},
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_116818_ActivityPlot|「群星」是祂的眼睛，代替祂注视，或者说监视着世间的一切。\n你以为你逃脱了祂的视线，但事实是——你仍在祂的梦中。\n「抓住你了——」\n捕获你的刹那，群星们发出了满足的叹息。",
