    ActivityTips = "Activity_95492_ActivityTips|<Title:简介>\n1、活动期间，守密人每天登录后可以在「君王的嘉赏」中领取当日签到奖励。\n2、奖励将根据守密人累计登录依次解锁，当日签到奖励将在9点（GMT+8）刷新。\n",
