    ActivityTips = "Activity_89899_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可使用「幻视单片镜」进行抽取。每次抽取所需要的「幻视单片镜」数量会增加。\n2、银枢幻衣有机会从第5次抽取开始获得。完成10次抽取必定获得当期银枢幻衣。\n3、活动结束后若有剩余「幻视单片镜」将自动转化为源液。",
