  [97995] = {
    ID = 97995,
    CnID = "活动@墨菲万圣节时装抽取活动",
    BaseSortID = 32,
    ActivityType = "TurntableActivity",
    ActivityPara1 = {97996},
    ActivityName = "Activity_97995_ActivityName|不发糖就捣蛋！",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Halloween02_small.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Halloween02.png",
    ActivityTips = "Activity_97995_ActivityTips|<Title:简介>\n诡异的烛火，欢闹的夜宴，狩猎糖果的小小女巫，于幽灵环绕下盛大登场！\n「打劫！把太妃糖、巧克力、奶糖、水果软糖……咳咳！总之把所有的糖果——全部给我装起来！」\n「你说棉花糖装起来不方便？呜……拿给我，我现在就把它们消灭掉！」。\n\n<Title:活动规则>\n1、活动期间，守密人可使用「怪味南瓜糖」抽取墨菲全新 4 星幻衣「糖果劫案」。\n2、首次抽取免费！每颗「怪味南瓜糖」购买需要「源液」×60，第 2 -10 次抽取分别需要「怪味南瓜糖」 ×1/2/2/3/5/5/5/5/5 。\n3、第5次抽取开始有机会获得 4 星幻衣，最多抽取10次必定获得当期 4 星幻衣。\n4、活动结束后，剩余「怪味南瓜糖」将以邮件形式回收并原价返还。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1760922000,
    ActivityEndTime = 1765760400,
    ActivityDisplay = 2,
    BannerPic = "UIResources/AtlasSource/UI_Main_Image/UI_Main_Activity_JP01.png",
