    },
    ActivityName = "Activity_66375_ActivityName|决胜：原初之影",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_WorldBoss1.png;UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_WorldBoss2.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map76.png;UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map77.png",
    ActivityTips = "Activity_66375_ActivityTips|<Title: 共战原初>\n·「共战原初」包含 7 个不可重现、直接挑战原初之视的关卡，活动首日开放前 3 个，之后每 3 天开放 1 个。\n·每次挑战战胜对应的原初之视后，即可获得对应奖励。\n·每种原初之视均有大量分身，每当某个种类的原初之视被任何守密人挑战胜利时，该类型原初之视的「世界残余数量」就会减少 1，当该类型原初之视的所有分身被消灭后，相应的关卡就会关闭，无法再次挑战。\n·所有关卡都受到「融灾黑潮·终末」的影响，但是每个关卡会提供不同的「纯银之芯」造物，将会为你提供强大的加成。此外，每个关卡还会提供「全知之眼」造物，将使塔薇在战斗开始时获得 120 狂气，塔薇所有造成的伤害、护盾、回复生命效果提高 50%。\n·所有关卡必须选择助战，整个活动中，每个互相关注的守密人只能为你提供一次助战。由于使用助战，因此实际同调率奖励会在奖励基础上再提高 50%。\n·守密人需要至少完成调查行动 2-9 才可以参与该活动。\n\n<Title:调查行动：终章>\n·每种原初之视的本体仍然需要在调查行动 9-5 至 9-11 中由你自己来击败。这些特殊关卡没有成就、没有星数，也没有「全知之眼」造物的帮助、也无法使用助战，同时更加困难。\n·在「共战原初」活动结束后即可解锁「调查行动：终章」的后续关卡。与其他守密人共同消灭各种原初之视的所有分身后，可以提前解锁调查行动 9-5 至 9-11 中对应的关卡。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1732928400,
    ActivityEndTime = 1734310800,
    ActivityStageCondition = 8126,
