    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_TeamSchool.png",
    ActivityTips = "Activity_70438_ActivityTips|<Title:活动简介>\n玩法活动「乌撒猫猫律」限时开放！活动期间，守密人可通过「群猫乱舞」暴打校猫，并且可以获得大量银芯和蔷薇金券！\n\n<Title:活动时间>\n1 月 24 日 9:00 - 2 月 5 日 9:00（GMT+8），活动期间每天均可参与当天解锁的「群猫乱舞」关卡，已结束的关卡内容不可再参与。\n\n<Title:群猫乱舞>\n1、「群猫乱舞」一共有 12 个关卡，每天开放不同的关卡，已结束的关卡内容不可再参与。\n2、每次挑战都不消耗「灵啡肽」，每完成 1 次关卡后可获得「无垢之芯」、「银芯」、「蔷薇金券」。\n3、本次关卡不可使用校友会助战。\n4、当天的关卡中，每个唤醒体只能出战 1 次。\n5、每天的关卡都需要用指定的界域进行挑战。\n·1 月 24 日：混沌界域\n·1 月 25 日：深海界域\n·1 月 26 日：血肉界域\n·1 月 27 日：超维界域\n·1 月 28 日：不限\n·1 月 29 日：不限\n·1 月 30 日：混沌界域与深海界域\n·1 月 31 日：血肉界域与超维界域\n·2 月  1 日：混沌界域与血肉界域\n·2 月 2 日：深海界域与超维界域\n·2 月 3 日：混沌界域与超维界域\n·2 月 4 日：血肉界域与深海界域",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1737680400,
    ActivityEndTime = 1738717200,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_70438_ActivityPlot|祈岁节将近，所有人都在关注庆典的筹备，并未留意到角落里漆黑的色块正在悄悄蠕动，小小囚犯化作液体逃离了牢笼。\n随着维度的裂隙闪烁，黑色毛团开始分裂......一片片黑色的猫海正在吞噬整个校园！\n你本想对此视而不见，将这种怪异事件交给校务处处理就好。\n但是看在它们会掉落银芯和金券的份上，你改变了主意。",
    ActivityDisplay = 2,
    BannerPic = "UIResources/AtlasSource/UI_Main_Image/UI_Main_Activity_26.png",
