    ActivityName = "Activity_81771_ActivityName|窥觑神国的阴影",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_OceanBoss.png",
    ActivityTips = "Activity_81771_ActivityTips|<Title: 异动海潮>\n·「异动海潮」包含 7 个关卡，活动首日开放前 3 个，之后每 3 天开放 1 个。每个关卡都有不同的丰厚奖励！\n·每种「异动海潮」均有大量集群，每当某个种类的集群被任何守密人挑战胜利时，该类型「异动海潮」的集群数量就会减少 1，当该类型异动海潮的所有集群被消灭后，相应的关卡就会关闭，无法再次挑战。\n·每位守密人每天最多可以击退 20 次「异动海潮」集群，活动持续期间每日 9:00（GMT+8）重置次数。\n·每个关卡会提供不同的造物，将会为你提供强大的加成。\n·所有关卡必须选择助战，整个活动中，每个互相关注的守密人只能为你提供一次助战。\n·守密人需要至少完成调查行动 2-9 才可以参与该活动。\n\n<Title: 等级补偿>\n·在「窥觑神国的阴影：异动海潮」中有等级补偿机制，以便各位守密人能够共同抵御入侵！\n等级补偿规则如下：\n ·调查队伍中，等级不足 60 级的唤醒体在本次挑战中将会补偿至 60 级。\n·调查队伍中，技能等级不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n·调查队伍中，「疯狂预兆」不足 6 级的唤醒体在本次挑战中将会补偿至 6 级。\n·调查队伍中，「灵塑适性」不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n ·若守密人等级不足60级，在本次挑战中将会补偿至60级。\n\n<Title:限时任务>\n·活动期间，累计击退 30 次异动海潮即可完成限时任务，获得「简易幻衣绘形券（一期）」×1！\n·在5 月 26 日 9:00 - 6 月 9 日 9:00（GMT+8）期间，可以在「商店：幻衣订购」使用「简易幻衣绘形券（一期）」兑换简约幻衣。\n·更多获取「简易幻衣绘形券（一期）」的方式可在社区和公告中了解。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1748221200,
    ActivityEndTime = 1753405200,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_81771_ActivityPlot|无人窥见神国的圣辉，但从那偶然泄露的真相里，人们能够感知到神国的阴影。\n它就在那里，一直在那里，而无数的虔诚者会让它真正降临。\n无论要犯下怎样深重的罪孽作为代价。",
