    ActivityPara3 = {95184},
    ActivityPara4 = {95258},
    ActivityName = "Activity_140082_ActivityName|坠临的万千耀光·复刻",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_KathiguRa.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map48.png",
    ActivityTips = "Activity_140082_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「烬灭追猎」、「无纷之宴」和「成就奖励」收集活动货币「财富之「印」」、「死亡之「印」」、「战争之「印」」，「财富之「印」」、「死亡之「印」」、「战争之「印」」可在「隐秘的据点」中购买商品，包括活动限定SR命轮「迫近的太阳」、流明之芯、无垢之芯等。\n2、活动期间，「不朽极昼」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：凯蒂古拉」！\n\n<Title:活动时间>\n1、9 月 7 日 9:00 - 10 月 5 日 9:00（GMT+8），所有活动玩法均可参与。\n2、10 月 5 日 9:00 - 10 月 12 日 9:00（GMT+8），仅可参与「隐秘的据点」和成就奖励。\n\n<Title:烬灭追猎>\n1、「烬灭追猎」包含 7 个关卡，每 1 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 隐秘的据点>\n「隐秘的据点」共有三个商店，开启时间如下：\n·「藏品宝库」： 9 月 7 日 9 时开启。\n·「委托密室」： 9 月 8 日 9 时开启。\n·「作战营帐」： 9 月 9 日 9 时开启。\n在商店内可以选择商品直接进行购买。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「烬灭追猎」关卡任务报酬中的「财富之「印」」、「死亡之「印」」、「战争之「印」」获得额外的掉落加成，具体加成如下：\n·唤醒体「凯蒂古拉」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「琥珀色的死亡」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「迫近的太阳」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title: 无纷之宴>\n1、每小时自动获得 60「财富之「印」」，最多储存 25 小时。\n\n<Title:意识潜游>\n1、活动期间，「不朽极昼」可免费解锁。\n2、活动结束后，「不朽极昼」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「不朽极昼」，活动结束后仍然可以消耗「现实起点」×3解锁。\n3、无论是否在活动期间，通关「意识潜游：不朽极昼」后都可以获得「钥令：不落的太阳」。",
