    ActivityEndTime = 1788138000,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_145458_ActivityPlot|贪婪的英雄想要不朽的王座，绝望的母亲想要复生的子，疯狂的术士想要禁忌的知识—— 他们跪在祂的面前，用祂听了万年的措辞乞求。\n祂赐予他们一切，然后看他们失去一切。祂看过四千场惨烈的角逐，却从不餍足。\n这一次，斗兽场的大门为你敞开。来吧，告诉祂，你渴望着什么。\n告诉祂，你与那四千个亡魂，究竟有何不同。",
