    ActivityTips = "Activity_141535_ActivityTips|<Title:活动简介>\n1、活动期间，「异梦视界：再见永无乡」限时免费解锁！\n2、活动期间，累计登录 7 天可在「彻夏狂欢」中获得「流明之芯」×10，第 7 天可额外获得限定对战头像「排球『大将』」。\n\n<Title:活动时间>\n1、7 月 6 日 9:00 - 7 月 20 日 9:00（GMT+8），所有活动均可参与。\n\n<Title:异梦视界>\n1、活动期间，「异梦视界：再见永无乡」可免费解锁。\n2、活动结束后，「异梦视界：再见永无乡」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「异梦视界：再见永无乡」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「异梦视界：再见永无乡」后都可以获得「钥令：定格的仲夏留念」。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1783299600,
    ActivityEndTime = 1784509200,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_141535_ActivityPlot|夏日、海滨、艳阳，以及众多熟悉的面孔。\n在黑阳的照耀下，忘记一切，沉沦于这场满足所有幻想的狂欢美梦中吧。",
