    ActivityName = "Activity_130175_ActivityName|颠倒的新生",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Saya.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map48.png",
    ActivityTips = "Activity_130175_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「暗室手记」和「成就奖励」收集活动货币「纯白鳞粉」「红色鳞粉」「耀光鳞粉」，并在「蒲公英园圃」中兑换商品，包括活动限定SR命轮「淤泥里的童话」、流明之芯、无垢之芯等。\n2、活动期间，「多维连接：被遗忘的爱之种」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：沙耶」！\n\n<Title:活动时间>\n1、5 月 30 日 9:00 - 8 月 24 日 9:00（GMT+8），所有活动玩法均可参与。\n2、8 月 24 日 9:00 - 8 月 31 日 9:00（GMT+8），仅可参与「蒲公英园圃」和成就奖励。\n\n<Title:暗室手记>\n1、「暗室手记」包含 7 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 蒲公英园圃>\n1、「蒲公英园圃」共有三个商店，开启时间如下：\n·「育种园圃」： 5 月 30 日 9 时开启。\n·「生长园圃」： 5 月 31 日 9 时开启。\n·「盛开园圃」： 6 月 1 日 9 时开启。\n2、每次交换将消耗「纯白鳞粉」/「红色鳞粉」/「耀光鳞粉」× 750，随机获得「蒲公英园圃」中的五个物品奖励。\n3、每个「蒲公英园圃」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「暗室手记」关卡任务报酬中三种活动货币的掉落获得额外加成：\n·唤醒体「沙耶」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「愿世界化作芬芳」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「淤泥里的童话」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、多项「活动加成」可叠加计算。 \n3、注意，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title:多维连接>\n1、活动期间，「多维连接：被遗忘的爱之种」可免费解锁。\n2、活动结束后，调查进度将保留，活动期间未完成的调查事件在活动后继续完成同样可获得对应奖励。如活动期间未解锁，活动结束后仍可消耗「现实起点」× 3 解锁。\n3、无论是否在活动期间，通关「多维连接：被遗忘的爱之种」均可获得「钥令：献给新世界」。",
