    ActivityTips = "Activity_133272_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「神圣的猎食」收集活动货币「美味雷欧烤肉」，「美味雷欧烤肉」可在「敬献贡礼」中购买商品，包括流明之芯、无垢之芯等。\n2、活动期间，「异梦视界：征厨房记」限时免费解锁。\n\n<Title:活动时间>\n1、5 月 4 日 9:00 - 5 月 18 日 9:00（GMT+8），所有活动玩法均可参与。\n2、5 月 18 日 9:00 - 5 月 25 日 9:00（GMT+8），仅可参与「敬献贡礼」和成就奖励。\n\n<Title:神圣的猎食>\n1、「神圣的猎食」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 敬献贡礼>\n在「敬献贡礼」商店内可以使用活动货币「美味雷欧烤肉」选择商品直接进行购买。\n\n<Title:异梦视界>\n1、活动期间，「异梦视界：征厨房记」可免费解锁。\n2、活动结束后，「异梦视界：征厨房记」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「异梦视界：征厨房记」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「异梦视界：征厨房记」后都可以获得「钥令：猎食决心」。",
