    ActivityPara2 = "126280,126298,126277",
    ActivityName = "Activity_126275_ActivityName|织者自缚",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Arachne.png",
    ActivityTips = "Activity_126275_ActivityTips|<Title:活动简介>\n活动期间，守密人可通过限时玩法「木偶的舞台」和「成就奖励」收集活动货币「丝绒座票根」，「丝绒座票根」可在「剧院礼品店」中换取奖励，包括活动限定SR命轮「宿命纺轮」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n\n<Title:木偶的舞台>\n1、「木偶的舞台」包含 5 个无需探索直接战斗的素材关卡，每 2 天开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得培养素材和活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「木偶的舞台」关卡任务报酬中的「丝绒座票根」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「阿拉克涅」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「永世编织之网」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「宿命纺轮」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title: 剧院礼品店>\n1、每次「礼品兑换」将消耗 750「丝绒座票根」，随机获得「剧院礼品店」中的五个物品奖励。\n2、「剧院礼品店」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 5 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 6 次及之后重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动时间>\n1、4 月 20 日 9:00 - 5 月 18 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、5 月 18 日 9:00 - 5 月 25 日 9:00（GMT+8），仅保留「剧院礼品店」和「成就奖励」，其他内容均已结束不可参与。\n3、5 月 25 日 9:00（GMT+8）后，剩余未兑换的「丝绒座票根」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1776646800,
    ActivityEndTime = 1779670800,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_126275_ActivityPlot|纺轮轻转，亘古不停。沿着丝线起舞吧，伟大的编织者。命运，是你无法逃离的舞台。\n审判者。救赎者。主人。囚徒……\n在踏入这座舞台之时，属于你的角色，早已无从选择。",
