    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map48.png",
    ActivityTips = "Activity_124801_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过参与「相位对弈」来完成「成就奖励」中的成就，并领取「魔法橡果」。\n2、「魔法橡果」可以在「回合奇赏」中领取丰富的奖励，包括活动限定头像「逆转回合：万象牌」、10个活动限定表情，以及「碎裂余梦」、「群星余梦」等。\n3、活动期间「多维连接：逆转回合」将免费开放！\n4、活动期间，通关了「多维连接：逆转回合：来自异界的客人」的守密人，「相位对弈」对战背景会限时替换为「逆转回合：意识空间」。\n\n<Title: 成就奖励>\n1、「成就奖励」中包含了「秘仪试炼」、「荣勋试炼」、「阈限试炼」，守密人可以通过完成成就目标领取「魔法橡果」。\n2、在「秘仪试炼」成就中\n·每击败 3 名对方唤醒体即可获得「魔法橡果」× 10，最多可以完成 50 次。\n·每释放 6 次狂气爆发即可获得「魔法橡果」× 10，最多可以完成 50 次。\n·每打出 20 张卡牌即可获得「魔法橡果」× 10，最多可以完成 50 次。\n3、核心课题临时解锁的「唤醒体」、「命轮」、「钥令」将会正常进行「成就奖励」计数。友谊赛与密码对弈无法进行「成就奖励」计数。\n\n<Title: 回合奇赏>\n1、守密人累积「魔法橡果」即可领取对应奖励，累积「魔法橡果」× 3600 能够获得全部核心奖励，累积「魔法橡果」× 6000 就可以获得所有奖励！\n2、通关「逆转回合：来自异界的客人」后解锁积累 100-900「魔法橡果」的奖励，通关「逆转回合：逆转万象的瞬间」后解锁积累 1000-6000「魔法橡果」的奖励。\n\n<Title: 多维连接>\n1、活动期间「多维连接：逆转回合」将免费开放。\n2、活动结束后，「多维连接：逆转回合」的调查进度会保留，如果活动期间未解锁「多维连接：逆转回合」，活动结束后仍然可以消耗「现实起点」×3解锁。\n3、无论是否在活动期间，通关「多维连接：逆转回合」后都可以获得「钥令：酒馆之门」。\n\n<Title:活动时间>\n本次活动仅在3 月 16 日 9:00 - 3 月 30 日 9:00（GMT+8）期间开放，3 月 30 日 9:00（GMT+8）后活动结束，请各位守密人记得领取「回合奇赏」中的奖励哦！",
