    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Xu.png",
    ActivityTips = "Activity_125364_ActivityTips|<Title:活动简介>\n活动期间，守密人可通过限时玩法「玄女无相」和「成就奖励」收集活动货币「梨膏糖」，「梨膏糖」可在「荒宅野奉」中换取奖励，包括活动限定SR命轮「玉兰之饵」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n\n<Title:玄女无相>\n1、「玄女无相」包含 9 个无需探索直接战斗的素材关卡，每天开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得培养素材和活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「玄女无相」关卡任务报酬中的「梨膏糖」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「徐」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「枉蹙眉」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「玉兰之饵」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title: 荒宅野奉>\n1、每次「供奉」将消耗 750「梨膏糖」，随机获得「荒宅野奉」中的五个物品奖励。\n2、「荒宅野奉」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 5 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 6 次及之后重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:意识潜游>\n1、活动期间，「扇下夜谈」可免费解锁。\n2、活动结束后，「扇下夜谈」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「扇下夜谈」，活动结束后仍然可以消耗「现实起点」×3解锁。\n3、无论是否在活动期间，通关「意识潜游：扇下夜谈」后都可以获得「钥令：深宅往事」。\n\n<Title:活动时间>\n1、1 月 26 日 9:00 - 2 月 9 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、2 月 9 日 9:00 - 2 月 16 日 9:00（GMT+8），仅保留「荒宅野奉」和「成就奖励」，其他内容均已结束不可参与。\n3、2 月 16 日 9:00（GMT+8）后，剩余未兑换的「梨膏糖」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。",
