    ActivityPlot = "Activity_122520_ActivityPlot|那场朦胧又潮湿的夜雨中，有一场注定的相逢在等待你。\n你记得她的名字，熟悉她的样貌， 那和缓而优雅的嗓音总让你如此安心。\n只是你忘了，乐于满足人类愿望的，从来只有神明与魔鬼。\n猜一猜，她属于哪一个？",
