    ActivityTips = "Activity_122195_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「迷失的自我」和「成就奖励」收集活动货币「迷雾之视」、「迷雾之梦」、「迷雾之源」，「迷雾之视」、「迷雾之梦」、「迷雾之源」可在「茉夏的小屋」中购买商品，包括活动限定SR命轮「理智明灯」、流明之芯、无垢之芯等。\n2、活动期间，「多维连接：银与血的洗礼」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：茉夏」！\n\n<Title:活动时间>\n1、12 月 29 日 9:00 - 1 月 12 日 9:00（GMT+8），所有活动玩法均可参与。\n2、1 月 12 日 9:00 - 1 月 19 日 9:00（GMT+8），仅可参与「茉夏的小屋」和成就奖励。\n\n<Title:迷失的自我>\n1、「迷失的自我」包含 7 个关卡，每 1 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 茉夏的小屋>\n「茉夏的小屋」共有三个商店，开启时间如下：\n·「材料室」： 12 月 29 日 9 时开启。\n·「入梦室」： 12 月 30 日 9 时开启。\n·「培养室」： 12 月 31 日 9 时开启。\n在商店内可以选择商品直接进行购买。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「迷失的自我」关卡任务报酬中的「迷雾之视」、「迷雾之梦」、「迷雾之源」获得额外的掉落加成，具体加成如下：\n·唤醒体「茉夏」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「狂戮至世界尽头」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「理智明灯」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title:多维连接>\n1、活动期间，「多维连接：银与血的洗礼」可免费解锁。\n2、活动结束后，「多维连接：银与血的洗礼」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「多维连接：银与血的洗礼」，活动结束后仍然可以消耗「现实起点」×3解锁。\n3、无论是否在活动期间，通关「多维连接：银与血的洗礼」后都可以获得「钥令：来自雾境」。",
