    ActivityTips = "Activity_97672_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「创生七日」、和「成就奖励」收集活动货币「安神香薰」、「驱魇香薰」、「捕梦香薰」，「安神香薰」、「驱魇香薰」、「捕梦香薰」可在「神母寝宫」中购买商品，包括活动限定SR命轮「蓝环毒素」、流明之芯、无垢之芯等。\n2、活动期间完成活动成就还能获得活动限定头像「以银钥之名：诞妄·墨菲」！\n\n<Title:活动时间>\n1、11 月 24 日 9:00 - 12 月 15 日 9:00（GMT+8），所有活动玩法均可参与。\n2、12 月 15 日 9:00 - 12 月 22 日 9:00（GMT+8），仅可参与「神母寝宫」和成就奖励。\n\n<Title:创生七日>\n1、「创生七日」包含 7 个关卡，每 1 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 亵祷狂欢>\n·活动开始后，每小时自动获得60「安神香薰」，最多储存 25 小时。\n\n<Title: 神母寝宫>\n1、「神母寝宫」共有三个商店，开启时间如下：\n·「异途甜梦」： 11 月 24 日 9 时开启。\n·「诞神深梦」： 11 月 25 日 9 时开启。\n·「无望梦魇」： 11 月 26 日 9 时开启。\n2、每次进奉将消耗 750「安神香薰」/「驱魇香薰」/「捕梦香薰」，随机获得寝宫中的五个物品奖励。\n3、每个寝宫的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续进奉，当「普通物品」也无剩余数量后，须进行重置才可以继续进奉。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「创生七日」关卡任务报酬中的「安神香薰」、「驱魇香薰」、「捕梦香薰」获得额外的掉落加成，具体加成如下：\n·唤醒体「诞妄·墨菲」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「黑暗中的安眠」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「蓝环毒素」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。",
