    ActivityPara3 = {99734},
    ActivityPara4 = {116505},
    ActivityName = "Activity_116470_ActivityName|极昼的终夜",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Pollux.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map48.png",
    ActivityTips = "Activity_116470_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「交融的苦血」、和「成就奖励」收集活动货币「觐见奉礼」、「忏悔奉礼」、「忠诚奉礼」，「觐见奉礼」、「忏悔奉礼」、「忠诚奉礼」可在「赐福仪式」中购买商品，包括活动限定SR命轮「圣子尊容」、流明之芯、无垢之芯等。\n2、活动期间，「异梦视界：天边之外·下」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：波吕克斯」！\n\n<Title:活动时间>\n1、10 月 20 日 9:00 - 11 月 3 日 9:00（GMT+8），所有活动玩法均可参与。\n2、11 月 3 日 9:00 - 11 月 10 日 9:00（GMT+8），仅可参与「赐福仪式」和成就奖励。\n\n<Title:交融的苦血>\n1、「交融的苦血」包含 7 个关卡，每 1 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 回忆漩涡>\n·活动开始后，每小时自动获得60「觐见奉礼」，最多储存 25 小时。\n\n<Title: 赐福仪式>\n1、「赐福仪式」共有三个商店，开启时间如下：\n·「濯洗肉身」： 10 月 20 日 9 时开启。\n·「忏悔灵魂」： 10 月 21 日 9 时开启。\n·「析出罪孽」： 10 月 22 日 9 时开启。\n2、每次交换将消耗 750「觐见奉礼」/「忏悔奉礼」/「忠诚奉礼」，随机获得画室中的五个物品奖励。\n3、每个画室的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「交融的苦血」关卡任务报酬中的「觐见奉礼」、「忏悔奉礼」、「忠诚奉礼」获得额外的掉落加成，具体加成如下：\n·唤醒体「波吕克斯」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「扭曲的骑士诗」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「圣子尊容」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title:异梦视界>\n1、活动期间，「异梦视界：天边之外·下」可免费解锁。\n2、活动结束后，「异梦视界：天边之外·下」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「异梦视界：天边之外·下」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「异梦视界：天边之外·下」后都可以获得「钥令：泣血的圣心」。",
