    ActivityPlot = "Activity_67721_ActivityPlot|少女们的笑声响起，回荡在大火尚未燃起的花园。\n为这美丽的往昔驻足吧，我的朋友。\n听尚未凋零的春天，轻声讲述过去的故事。",
