    ActivityPlot = "Activity_95191_ActivityPlot|它们高颂永不遗忘的歌，迎接永不熄灭的主。\n祂将携万千耀光自极天坠下，诉说永世不灭的辉煌。\n当祂降临之时，琥珀色的光便覆罩了世界。\n这是祂送给世界的葬礼。",
