    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Doresain.png",
    ActivityTips = "Activity_95977_ActivityTips|<Title:活动简介>\n活动期间，守密人可通过限时玩法「噬灵之飨」和「成就奖励」收集活动货币，活动货币可在「王邸餐厅」中用于交换从而获得道具奖励，包括活动限定SR命轮「珍馐」、贤者之石、无垢之芯、流明之芯等。\n\n<Title:活动时间>\n1、7 月 21 日 9:00 - 8 月 4 日 9:00（GMT+8），所有活动内容均可参与。\n2、8 月 4 日 9:00 - 8 月 11 日 9:00（GMT+8），仅保留「王邸餐厅」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 噬灵之飨>\n1、「噬灵之飨」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title: 活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「噬灵之飨」关卡任务报酬中的「腐坏手骨」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「杜勒赛因」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「安息之吻」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「珍馐」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title:  王邸餐厅>\n1、每次「提交报告」将消耗 750「腐坏手骨」，随机获得「王邸餐厅」中的五个物品奖励。\n2、「王邸餐厅」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 5 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 6 次及之后重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n3、8 月 11 日 9:00（GMT+8）后，剩余未兑换的「腐坏手骨」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。",
