  [81019] = {
    ID = 81019,
    CnID = "活动@黄金周活动",
    BaseSortID = 112,
    ActivityType = "GoldenWeekActivity",
    ActivityPara1 = {81006},
    ActivityPara2 = "81017,80995",
    ActivityPara3 = {81021},
    ActivityName = "Activity_81019_ActivityName|扫除奇旅",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Karen.png",
    ActivityTips = "Activity_81019_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过参与「扫除进度」并领取「清扫工具」。\n2、「清扫工具」积累到一定数量后可以在「除尘津贴」中领取丰富的奖励，包括活动限定头像「清理大师」、银芯、无垢之芯、贤石碎屑等。\n\n<Title: 扫除进度>\n1、「扫除进度」中包含了多个不同类型的清扫任务，守密人可以通过完成清扫任务来领取「清扫工具」，每日完成所有类型的清扫任务后还有一份额外的奖励！\n2、活动期间，每首次完成 1 种清扫任务就会播放隐藏剧情。\n3、「扫除进度」会在活动期间的每日 9:00（GMT+8）刷新重置。\n\n<Title: 除尘津贴>\n1、守密人累积「清扫工具」即可领取对应奖励，每达到 1000「清扫工具」可领取丰厚的物资奖励，累计达到 10000「清扫工具」可获得扫除奇旅专属头像「清理大师」。\n\n<Title:珈伦的谢礼>\n活动期间，可以在「珈伦的谢礼」处签到领取伽伦给守密人准备的谢礼！\n\n<Title:活动时间>\n本次活动仅在4 月 28 日 9:00 - 5 月 12 日 9:00（GMT+8）期间开放，5 月 12 日 9:00（GMT+8）后活动结束，请各位守密人记得领取「除尘津贴」中的奖励哦！",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1745802000,
    ActivityEndTime = 1747011600,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_81019_ActivityPlot|是谁穿梭于梦幻的卡达斯，替主人清理垃圾？\n是珈伦~是珈伦！\n清理融蚀~梦境通风~维度消毒~把一切都打扫干净~\n毕竟在清扫方面，珈伦我可是专业的！\n主人要来试试么！珈伦会把清扫之法，毫无保留的教给主人的！",
