  [68406] = {
    ID = 68406,
    CnID = "活动@克莱门汀活动",
    BaseSortID = 115,
    ActivityType = "ClementineActivity",
    ActivitySystemType = "AwakerActivityShop",
    ActivityPara1 = {44, 79567},
    ActivityPara2 = "79490,79483,79500",
    ActivityName = "Activity_68406_ActivityName|埋于记忆之下",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Clementine.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map83.png",
    ActivityTips = "Activity_68406_ActivityTips|<Title:活动简介>\n活动期间，守密人可通过限时玩法「恐惧愈疗」和「成就奖励」收集活动货币，活动货币可在「 神经诊疗室」中用于交换从而获得道具奖励，包括活动限定SR命轮「催眠灵摆」、贤者之石、无垢之芯、流明之芯等。\n\n<Title:活动时间>\n1、4 月 7 日 9:00 - 4 月 21 日 9:00（GMT+8），所有活动内容均可参与。\n2、4 月 21 日 9:00 - 4 月 28 日 9:00（GMT+8），仅保留「 神经诊疗室」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 恐惧愈疗>\n1、「恐惧愈疗」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title: 活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「恐惧愈疗」关卡任务报酬中的「诊断报告」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「克莱门汀」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「隐没的痛楚」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「催眠灵摆」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title:  神经诊疗室>\n1、每次「提交报告」将消耗 1000「诊断报告」，随机获得「 神经诊疗室」中的五个物品奖励。\n2、「 神经诊疗室」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 5 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 6 次及之后重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n3、4 月 28 日 9:00（GMT+8）后，剩余未兑换的「诊断报告」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1743987600,
    ActivityEndTime = 1745802000,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_68406_ActivityPlot|人们将渴求之物深埋在记忆深处，带上虚幻的假面迎合世界。\n听啊，被血肉皮囊遮盖之物的呐喊，正在记忆的迷雾中回荡。\n放空思想，抛去血肉，去迎接真实的自己。",
    ActivityDisplay = 2,
    BannerPic = "UIResources/AtlasSource/UI_Main_Image/UI_Main_Activity_29.png",
    BannerText = "Activity_68406_BannerText|玩法活动限时开启！",
    ActivityStageEndTime = 1745197200,
    ActivityStageEndContent = "Activity_68406_ActivityStageEndContent|活动已结束，当前仅可参与「神经诊疗室」"
  },
