    ActivityTips = "Activity_72101_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过参与「相位对弈」来完成「成就奖励」中的成就，并领取「魔法橡果」。\n2、「魔法橡果」可以在「回合奇赏」中领取丰富的奖励，包括活动限定头像「逆转回合：万象牌」、10个活动限定表情，以及「碎裂余梦」、「群星余梦」等。\n3、活动期间「多维连接：逆转回合」将免费开放！\n4、活动期间，通关了「多维连接：逆转回合：来自异界的客人」的守密人，「相位对弈」对战背景会限时替换为「逆转回合：意识空间」。\n\n<Title: 成就奖励>\n1、「成就奖励」中包含了「唤醒体」获胜成就、「命轮」获胜成就、「钥令」获胜成就、出牌数量成就，守密人可以通过完成成就领取「魔法橡果」。\n2、在「相位对弈」使用不同职业的「唤醒体」每打出25张卡牌即可获得30个「魔法橡果」。每个职业的「出牌」成就最多可以完成80次。\n3、「唤醒体」成就：每个「唤醒体」在「相位对弈」中完成1/3/6/10次胜利时可以获得10个「魔法橡果」。\n4、「命轮」成就：每个「命轮」在「相位对弈」中完成1/3/6次胜利时可以获得10个「魔法橡果」。\n5、「钥令」成就：每个「钥令」在「相位对弈」中完成1/3/6次胜利时可以获得10个「魔法橡果」。\n6、核心课题临时解锁的「唤醒体」、「命轮」、「钥令」将会正常进行胜利计数和出牌计数，但是需要在获得对应的「唤醒体」、「命轮」、「钥令」后才能领取胜利成就奖励。\n\n<Title: 回合奇赏>\n1、守密人累积「魔法橡果」即可领取对应奖励，累积 2500「魔法橡果」能够获得全部核心奖励，累积 5000「魔法橡果」就可以获得所有奖励！\n2、通关「逆转回合：来自异界的客人」后解锁积累100-900「魔法橡果」的奖励，通关「逆转回合：逆转万象的瞬间」后解锁积累1000-5000「魔法橡果」的奖励。\n\n<Title: 多维连接>\n1、活动期间「多维连接：逆转回合」将免费开放。\n2、活动期间，「逆转回合：贯彻意志的绝对」需要积攒1000「魔法橡果」才能解锁。\n3、活动结束后，「多维连接：逆转回合」的调查进度会保留，如果活动期间未解锁「多维连接：逆转回合」，活动结束后仍然可以消耗「现实起点」×3解锁。\n3、无论是否在活动期间，通关「多维连接：逆转回合」后都可以获得「钥令：酒馆之门」。\n\n<Title:活动时间>\n本次活动仅在3 月 18 日 9:00 - 4 月 1 日 9:00（GMT+8）期间开放，4 月 1 日 9:00（GMT+8）后活动结束，请各位守密人记得领取「回合奇赏」中的奖励哦！",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1742259600,
    ActivityEndTime = 1743469200,
    ActivityStageCondition = 8111,
    UnlockConditionExplanation = "Activity_72101_UnlockConditionExplanation|完成 「调查行动」3-2·普通 后解锁",
    ActivityPlot = "Activity_72101_ActivityPlot|“我要让所有人都玩万象牌！”\n其他时空的来客因为一场意外进入了相位对弈的空间，将其改造成了与原先大不相同的样子。\n为了将空间再次逆转，不同时空的守密人将要决出一位最强者，向这名来客发起挑战。",
    ActivityDisplay = 2,
