    ActivityPara2 = "56414,56416,57137",
    ActivityName = "Activity_73879_ActivityName|群星正位·复刻",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map69_small.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map48.png",
    ShowAwaker = 15576,
    ActivityTips = "Activity_73879_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「黑暗子宫」和「成就奖励」收集三种「胚胎」，「胚胎」可在「圣胎孵化」中兑换道具奖励，包括活动限定SR命轮「冰川下的沉眠」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间，完成「成就奖励」的任务可获得活动限定头像「以银钥之名：墨菲」、活动限定SR命轮「冰川下的沉眠」和大量「胚胎」。\n\n<Title:活动时间>\n1、3 月 10 日 9:00 - 3 月 24 日 9:00（GMT+8），所有活动内容均可参与。\n2、3 月 24 日 9:00 - 3 月 31 日 9:00（GMT+8），仅保留「圣胎孵化」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 黑暗子宫>\n1、「黑暗子宫」包含 7 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「无识之胚」、「无欲之胚」和「无厌之胚」。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n5、通关关卡任意难度后，解锁该关卡的癫狂难度。完成癫狂难度首通可获得丰厚的活动货币奖励。\n6、请注意：癫狂难度挑战不消耗灵啡肽，不可重现，且首通后重复挑战不会再获得活动货币奖励。\n\n<Title: 胚胎加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「黑暗子宫」关卡任务报酬中的「无识之胚」、「无欲之胚」和「无厌之胚」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「墨菲」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「隐秘的诞生」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「冰川下的沉眠」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「胚胎加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「胚胎加成」影响。\n\n<Title: 圣胎孵化>\n1、「圣胎孵化」仅在 3 月 10 日 9:00 - 3 月 31 日 9:00（GMT+8）期间开放。\n2、3 月 31 日 9:00（GMT+8）后，剩余未兑换的「胚胎」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1741568400,
    ActivityEndTime = 1743382800,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_73879_ActivityPlot|群星正位之刻将至，胸前胎动如鼓。\n折磨她多年的暗夜噩梦，伴随无数信徒热泪盈眶的终局到来。\n自祂@1黑暗的@2中，伟大的@3降临世界。",
    ActivityDisplay = 2,
