    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map59_small.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map57.png",
    ActivityTips = "Activity_67727_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「紊乱情欲」和「成就奖励」收集活动货币「丰穰种核」，「丰穰种核」可在「欲孽滋生」中换取奖励，包括活动限定SR命轮「灼热的吻别」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n2、活动期间，「繁衍狂热」参与条件放宽至通关「调查行动」2-9·普通，且无需满足唤醒体同调率要求即可解锁「繁衍狂热事件」，此外，消耗的「现实起点」数量要求也变为仅需 1 个！\n3、一股神秘力量的到来似乎有助于你与唤醒体建立更深层次的关系，活动期间通过所有方式获取的同调率翻倍！\n\n<Title:紊乱情欲>\n1、「紊乱情欲」包含 10 个无需探索直接战斗的素材关卡，每天开放 1 个。\n2、在这些素材关卡中，你将直接觉醒所有唤醒体，并获得预设的造物，此外在 6 回合之后受到 1 次泰旖丝的帮助。\n3、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得培养素材和活动货币。\n4、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n5、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title:强欲加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「紊乱情欲」关卡任务报酬中的「丰穰种核」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「泰旖丝」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「慈悲的哺育」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「灼热的吻别」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「强欲加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title: 欲孽滋生>\n1、每次「交换种核」将消耗 1000「丰穰种核」，随机获得「欲孽滋生」中的五个物品奖励。\n3、「欲孽滋生」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 4 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 5 次及之后重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动时间>\n1、12 月 16 日 9:00 - 12 月 30 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、12 月 30 日 9:00 - 1 月 6 日 9:00（GMT+8），仅保留「欲孽滋生」和「成就奖励」，其他内容均已结束不可参与。\n3、1 月 6 日 9:00（GMT+8）后，剩余未兑换的「丰穰种核」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。",
