    ActivityTips = "Activity_53829_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「蔷薇忆事」和「成就奖励」收集活动货币「通灵鸟羽扇」，「通灵鸟羽扇」可在「金红庆典」中兑换丰厚奖励，包括活动限定SR命轮「百万蒙宠之眼」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间，完成「成就奖励」的任务可获得活动限定头像「以银钥之名：索蕾尔」、活动限定SR命轮「百万蒙宠之眼」、银芯和大量活动货币「通灵鸟羽扇」。\n3、活动期间，「特遣纪录：蔷薇礼赞」将免费开放。\n\n<Title:活动时间>\n1、7 月 1 日 9:00 - 7 月 15 日 9:00（GMT+8），所有活动内容均可参与。\n2、7 月 15 日 9:00 - 7 月 22 日 9:00（GMT+8），仅保留「金红庆典」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 蔷薇忆事>\n1、「蔷薇忆事」包含 9 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战不同的关卡除了获得不同的素材掉落外，还将获得活动货币「通灵鸟羽扇」。\n3、本次活动关卡为直接战斗的素材关卡，通关后可重现！每次「重现」消耗 「灵啡肽」× 120 。\n4、请注意：使用「重现」功能时，无法获得同调率。\n\n<Title: 羽扇加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「蔷薇忆事」关卡任务报酬中的「通灵鸟羽扇」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「索蕾尔」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「以蔷薇之名」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「百万蒙宠之眼」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「羽扇加成」以叠加的方式结算。\n\n<Title:特遣纪录>\n1、活动期间，此前已经解锁「特遣纪录：蔷薇礼赞」的守密人，重新解锁将会获得「通灵鸟羽扇」×600的补偿。\n2、在「特遣纪录：蔷薇礼赞」中，守密人将使用包含剧情预设「索蕾尔」的特殊编队进行挑战。",
