    ActivityPara4 = {52089},
    ActivityName = "Activity_52040_ActivityName|沉渊之祀",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map64_small.png",
    ShowAwaker = 15582,
    ActivityTips = "Activity_52040_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「神国诞临」、「王的谕旨」和「成就奖励」收集活动货币，活动货币可在「沉渊的回应」中用于进献从而获得道具奖励，包括活动限定SR命轮「深海的呼唤」、贤者之石、无垢之芯、流明之芯等。\n2、活动期间「异梦视界：亵渎」将免费开放。\n\n<Title:活动时间>\n1、6 月 17 日 9:00 - 7 月 1 日 9:00（GMT+8），所有活动内容均可参与。\n2、7 月 1 日 9:00 - 7 月 8 日 9:00（GMT+8），仅保留「沉渊的回应」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 神国诞临>\n1、「神国诞临」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「祀者之泪」、「祀者之血」和「祀者之髓」。双倍挑战时，需要消耗 240 灵啡肽，关卡任务报酬也会翻倍，同调率奖励不变。\n3、「成就奖励」完成度达到100%之后，解锁已通关关卡的「重现」功能。每次「重现」消耗 「灵啡肽」× 120 。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：海渊祭仪」来帮助你更轻松地通关。\n\n<Title: 祀物加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「神国诞临」关卡任务报酬中的「祀者之泪」、「祀者之血」和「祀者之髓」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「弥利亚姆」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「虔诚的伟力」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「深海的呼唤」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「祀物加成」以叠加的方式结算。\n\n<Title:共鸣：海渊祭仪>\n1、守密人可以通过完成活动成就获取「虔信之心」。 \n2、消耗「虔信之心」，激活「共鸣：海渊祭仪」，可以获得以下加成：\n（1）让守密人在活动玩法「神国诞临」中变得更强，挑战更加轻松。\n（2）提升完成「神国诞临」挑战后获得的活动货币。\n（3）激活活动玩法「王的谕旨」。\n\n<Title: 王的谕旨>\n·激活共鸣「祭献试炼」后，每小时自动获得60「祀者之泪」，最多储存 25 小时。\n\n<Title: 沉渊的回应>\n1、「沉渊的回应」共有三个祭坛，开启时间如下：\n·「莹泪祭坛」： 6 月 17 日 9 时开启。\n·「猩血祭坛」： 6 月 19 日 9 时开启。\n·「灵髓祭坛」： 6 月 21 日 9 时开启。\n2、每次进献祭品将消耗 500「祀者之泪」/「祀者之血」/「祀者之髓」，随机获得祭坛中的五个物品奖励。\n3、每个祭坛的物品奖励分为「神国的恩赐」和「凡庸的奖赏」两种，重置时可以使指定物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「神国的恩赐」无剩余数量后，守密人可以选择重置，重置后会将「神国的恩赐」和「凡庸的奖赏」的剩余数量重置至上限；也可以选择继续进献祭品，当「凡庸的奖赏」也无剩余数量后，须进行重置才可以继续进献祭品。\n（2）第3次开始重置：当「凡庸的奖赏」无剩余数量后才可以进行重置，重置会将「凡庸的奖赏」的剩余数量重置至上限，「神国的恩赐」不再重置。\n\n<Title: 异梦视界>\n1、「异梦视界」是全新的调查类型，相比通常的剧情演绎形式，「异梦视界」的将更侧重文字的表现，文字内容量也更多。\n2、在「异梦视界：亵渎」中，你将通过与弥利亚姆精神的链接，直接读取她的记忆，从而见证：尚为孩童的弥利亚姆一步步经历利莫里亚的苦难，在信仰中迷茫，在信仰中挣扎，最终走上了成为救世主与毁灭者的道路……\n3、活动期间「异梦视界：亵渎」将免费开放。每隔2天会推出新的事件，通关「异梦视界：亵渎」后可以在成就奖励中获得银芯、活动限定SR命轮「深海的呼唤」等奖励，成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n4、活动结束后，「异梦视界：亵渎」的调查进度会保留，如果活动期间未解锁「异梦视界：亵渎」，活动结束后仍然可以消耗「现实起点」×7解锁。\n5、无论是否在活动期间，通关「异梦视界：亵渎」后都可以获得「钥令：海之祭」。\n\n\n\n",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 1718586000,
