    ActivityPlot = "Activity_52040_ActivityPlot|深海的倒影上，王的梦境消散，神的国度也已腐朽。\n她从旧日的幻梦中走来，走入未来坍塌的废墟。\n她询问深渊，深渊缄默不语。\n她向深渊祭祀，回应她的，只有她自己。",
