  },
  [51127] = {
    ID = 51127,
    CnID = "活动@故事的魔法复刻活动",
    BaseSortID = 154,
    ActivityType = "MagicStoryActivityReproduce",
    ActivitySystemType = "AwakerActivityShop",
    ActivityPara1 = {28, 51137},
