    ActivityPara2 = "49383,49381",
    ActivityName = "Activity_48719_ActivityName|欲海翻波",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map59_small.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map57.png",
    ActivityTips = "Activity_48719_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「紊乱情欲」和「成就奖励」收集活动货币「丰穰种核」，「丰穰种核」可在「欲孽滋生」中换取奖励，包括流明之芯、无垢之芯和丰厚的培养素材。\n2、活动期间，守密人只要完成「调查行动」2-9·普通也可以参与「繁衍狂热」，且无需满足唤醒体同调率要求即可解锁「繁衍狂热事件」，此外，消耗的「现实起点」数量要求也变为仅需 1 个！\n3、一股神秘力量的到来似乎有助于你与唤醒体建立更深层次的关系，活动期间通过所有方式获取的同调率翻倍！\n\n<Title:活动时间>\n1、5 月 18 日 9:00 - 6 月 3 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、6 月 3 日 9:00 - 6 月 10 日 9:00（GMT+8），仅保留「欲孽滋生」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title:紊乱情欲>\n1、「紊乱情欲」包含 10 个无需探索直接战斗的素材关卡，每天开放 1 个。\n2、在这些素材关卡中，你将直接觉醒所有唤醒体，并获得预设的造物，此外在 6 回合之后受到 1 次泰旖丝的帮助。\n3、每次挑战将消耗 60 点灵啡肽，本次活动素材关卡通关后即可支持重现。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title:强欲加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「紊乱情欲」关卡任务报酬中的「丰穰种核」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「泰旖丝」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「慈悲的哺育」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「灼热的吻别」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「强欲加成」以叠加的方式结算。\n\n<Title:繁衍狂热>\n1、通关「调查行动」7-3·普通之后，全新特别调查内容「繁衍狂热」开放！\n2、随着「欲海翻波」活动的到来，让唤醒体们受到了神秘力量影响，陷入了「繁衍狂热」状态……请各位守密人小心！\n3、当唤醒体的同调率达到 10 级后可以解锁该唤醒体的「繁衍狂热事件」，消耗 「现实起点」×7 进行解锁，完成后可以获取「无垢之芯」×1！\n4、在「欲海翻波」活动期间（6 月 3 日 9:00前）参与条件放宽至通关「调查行动」2-9·普通，并且唤醒体无需同调率要求即可解锁「繁衍狂热事件」，此外消耗的「现实起点」数量要求也变为仅需 1 个！ \n\n<Title: 同调率翻倍>\n1、一股神秘力量的到来似乎有助于你与唤醒体建立更深层次的关系，活动期间通过所有方式获取的同调率翻倍！\n2、与其他同调率加成的奖励按照相乘的方式结算，如使用助战同调率加成。\n<Title:成就奖励>\n1、完成所有任务可以获得奖励：银芯×800，大量「丰穰种核」，活动限定 SR 命轮「灼热的吻别」×16，活动限定头像「以银钥之名：泰旖丝」。\n2、包含 16 个任务：通关「紊乱情欲」的每个关卡 1 次，「紊乱情欲」中累计重现 10/20/30/40/50 次，完成所有活动成就。\n\n\n\n",
