    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map57_small.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map57.png",
    ActivityTips = "Activity_46609_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「记忆编码」、「边缘存储」和「成就奖励」收集活动货币「记忆拼图」，「记忆拼图」可在「人格解析」中购买商品，包括活动限定SR命轮「银鳕鱼的决心」、流明之芯、无垢之芯、贤者之石和丰厚的培养素材。\n2、通关「特遣纪录：宁静的裂殖」可获得全新钥令「全部的她」。活动期间，「特遣纪录：宁静的裂殖」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：「24」」！\n\n<Title:活动时间>\n1、4 月 27 日 9:00 - 5 月 18 日 9:00（GMT+8），所有活动玩法均可参与，「特遣纪录：宁静的裂殖」限时免费解锁。\n2、5 月 18 日 9:00 - 5 月 25 日 9:00（GMT+8），仅可参与「人格解析」和成就奖励，「特遣纪录：宁静的裂殖」需要消耗现实起点×7解锁。\n\n<Title:记忆编码>\n1、「记忆编码」包含 5 个关卡，守密人通过完成「特遣纪录：宁静的裂殖」的第2/4/6/8/10关可逐个解锁。\n2、每个关卡都有 7 个难度，推荐等级为 15~65，所有难度均默认解锁。每个关卡的敌人与事件都可能发生随机变化。\n3、可以使用校友会助战和「共鸣：分离性症候」来帮助你更轻松地过关。\n4、每次挑战需要消耗 120 灵啡肽，难度越高，通关获取的「记忆拼图」就越多，此外守密人可以选择双倍挑战，消耗 240 灵啡肽，获得双倍的「记忆拼图」和守密人经验。\n\n<Title:理性加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「记忆编码」关卡任务报酬中的「记忆拼图」获得额外的掉落加成，具体加成如下：\n·唤醒体「24」：启灵0/1/2/3及以上，加成15%/20%/25%/30%。\n·唤醒体「达芙黛尔」：启灵0/1/2/3及以上，加成15%/20%/25%/30%。\n·SSR命轮「畸体回噬」：叠位0/1/2/3及以上，加成15%/20%/25%/30%。\n·SSR命轮「至为珍贵的藏品」：叠位0/1/2/3及以上，加成15%/20%/25%/30%。\n·SR命轮「银鳕鱼的决心」：叠位0/1/2/3及以上，加成15%/20%/25%/30%。\n2、不同唤醒体或命轮的「理性加成」以叠加的方式结算。 \n\n<Title:共鸣：分离性症候>\n1、守密人可以通过完成活动成就获取「分裂之心」。 \n2、消耗「分裂之心」，激活「共鸣：分离性症候」，可以获得以下加成：\n（1）让守密人在活动玩法「记忆编码」和「特遣纪录：宁静的裂殖」中变得更强，挑战更加轻松。\n（2）提升完成「记忆编码」挑战后获得的奖励。\n（3）激活活动玩法「边缘存储」。\n\n<Title: 边缘存储>\n·激活共鸣「诊断：人格分裂」后，每小时自动获得 60「记忆拼图α」，最多储存 25 小时。\n\n<Title:特遣纪录>\n1、活动期间，「特遣纪录：宁静的裂殖」可免费解锁。每隔2天会推出「宁静的裂殖」新的调查事件，完成调查事件后可以获得钥令「全部的她」、无垢之芯、调查徽章和守密人经验等调查奖励。\n2、活动结束后，「特遣纪录：宁静的裂殖」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「特遣纪录：宁静的裂殖」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、活动期间会推出限时成就奖励，守密人完成「特遣纪录：宁静的裂殖」的所有调查事件后，可以在活动成就中领取头像「以银钥之名：「24」」！成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n\n\n",
