    ActivityTips = "Activity_38805_ActivityTips|<Title:活动简介>\n·活动期间「燃烧的群宴」玩法限时开启，且「意识潜游：燃烧的群宴」限时免费解锁！\n\n<Title:湖中之城>\n·「湖中之城」有 7 个关卡，每 2 天开放 1 个！每个关卡的敌人与事件都可能发生随机变化。\n·请注意，每个关卡奖励的素材种类、数量、混合比例都可能发生变化，越早开放的关卡种类更单纯，越晚开放的关卡种类更丰富但总量会更多，请按自己的需要选择攻略方法吧！\n·每个关卡共包含 7 个难度的关卡，推荐等级范围为 15~65，所有难度均默认解锁。\n·每次挑战需要消耗灵啡肽×120，难度越高，获取的奖励就越多，请选择适合自己的难度进行挑战。\n·关卡奖励的素材可以在「旺达的奇珍宝匣」商店兑换大量的唤醒体培养素材，还有活动限定头像「以银钥之名：旺达」。\n·可以使用校友会助战和「共鸣：代行密令」来帮助你更轻松地过关。。\n\n<Title:共鸣与成就>\n·消耗「享乐之心」，激活「共鸣：代行密令」，可以让守密人在「湖中之城」中变得更强，挑战更加轻松；也可以让守密人在通关时获得额外的活动货币。\n·守密人可以通过达成活动成就获取「享乐之心」，也可在「旺达的奇珍宝匣」商店兑换。\n\n<Title:意识潜游>\n·活动期间，「燃烧的群宴」可免费解锁。每天会推出「燃烧的群宴」中一个新的调查事件，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「燃烧的群宴」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「燃烧的群宴」，活动结束后仍然可以消耗「现实起点」×3解锁。\n·活动期间会推出限时成就奖励，守密人完成「燃烧的群宴」的调查事件后，可以在活动成就中领取银芯奖励！成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n",
