    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events_Bg/UI_Events_Bg_Map_46.png",
    ShowAwaker = 15581,
    ActivityTips = "Activity_34755_ActivityTips|<Title:活动简介>\n·活动期间「剧本迷思」玩法限时开启，且「特遣纪录：故事的魔法」免费解锁开启！\n\n<Title:剧本迷思>\n·「剧本迷思」共包含 9 个难度的关卡，推荐等级范围为 30~70，通关较低的难度的关卡后解锁更高难度的关卡。\n·每次挑战需要消耗灵啡肽×60，每次通关后都可以获得活动货币「飘零的灵感」。关卡难度越高，获取的「飘零的灵感」就越多！\n·「飘零的灵感」可以在「魔法剧本商店」兑换大量的唤醒体培养素材，还可以兑换活动限定 SR 命轮「35mm的魔法」，该命轮在未来可能会再次推出或加入常驻唤醒。\n·每次挑战时，除首领之外的敌人、事件、地图都可能发生一定的变化，关卡内可能出现的造物也更多！\n·在「剧本迷思」中可以使用校友会助战。\n\n<Title:共鸣与成就>\n·消耗「演绎之心」，激活「共鸣：导演密码」，可以让守密人在「剧本迷思」中变得更强，挑战更加轻松。\n·守密人可以通过达成活动成就获取「演绎之心」，除此之外通过活动成就还可以获得活动限定头像「以银钥之名：莉莉」！\n\n<Title:特遣纪录>\n·活动期间，每天会推出「故事的魔法」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「故事的魔法」的调查进度会保留，守密人可以在特遣纪录中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。\n·活动期间会推出限时成就奖励，守密人通关「故事的魔法」普通模式和完成「故事的魔法」的调查事件后，可以在活动成就中领取银芯奖励！成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n",
