    ActivityTips = "Activity_71100_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可以通过限时玩法「深海凝视」和「成就奖励」收集活动货币「惫倦绪思」、「悲愁绪思」、「欢悦绪思」。活动货币可在「觉知海渊」中购买商品，包括活动限定SR命轮「青石王座」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n2、活动期间，完成活动成就还能获得活动限定头像「以银钥之名：凯刻斯」、活动限定SR命轮「青石王座」、银芯和大量活动货币！\n\n<Title:活动时间>\n1、12 月 30 日 9:00 - 1 月 13 日 9:00（GMT+8），所有活动玩法均可参与。\n2、1 月 13 日 9:00 - 1 月 20 日 9:00（GMT+8），仅可参与「觉知海渊」和成就奖励。\n\n<Title:深海凝视>\n1、「深海凝视」有 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title:绪思加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「深海凝视」关卡任务报酬中的活动货币获得额外的掉落加成，具体加成如下：\n·唤醒体「图鲁」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「神王的颂歌」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「青石王座」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「绪思加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「绪思加成」影响。\n\n<Title: 觉知海渊>\n1、「觉知海渊」仅在 12 月 30 日 9:00 - 1 月 20 日 9:00（GMT+8）期间开放。\n2、1 月 20 日 9:00（GMT+8）后，剩余未兑换的「惫倦绪思」、「悲愁绪思」、「欢悦绪思」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 4102448400,
    ActivityEndTime = 4102448400,
