    },
    ActivityName = "Activity_71102_ActivityName|故事的魔法·复刻",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map63_small.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events_Bg/UI_Events_Bg_Map_46.png",
    ShowAwaker = 15581,
    ActivityTips = "Activity_71102_ActivityTips|<Title:活动简介>\n1、玩法活动复刻「故事的魔法」限时开放，守密人可通过「魔法剧本商店」和「成就奖励」再次获得活动限定命轮「35mm 的魔法」与活动限定头像「以银钥之名：莉莉」！\n2、活动期间，「特遣纪录：故事的魔法」将限时免费解锁。\n\n<Title:活动时间>\n1、6 月 3 日 9:00 - 6 月 17 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、6 月 17 日 9:00 - 6 月 24 日 9:00（GMT+8），仅保留「魔法剧本商店」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title:剧本迷思>\n1、「剧本迷思」包含 9 个素材关卡，每天自动开放 1 个，开放后需通关前置特遣纪录关卡才可挑战。\n2、每次挑战将消耗 60 点灵啡肽，挑战成功将获得活动货币「飘零的灵感」和培养素材；本次活动素材关卡通关后即可支持重现。\n3、可以使用校友会助战和「共鸣：导演密码」来帮助你更轻松地通关。\n\n<Title:灵感加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「剧本迷思」关卡任务报酬中的「飘零的灵感」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「莉莉」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「跨越疼痛」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「35mm的魔法」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「灵感加成」以叠加的方式结算。\n\n<Title:共鸣：导演密码>\n1、守密人可以通过完成活动成就获取「演绎之心」。 \n2、消耗「演绎之心」，激活「共鸣：导演密码」，可以让守密人在活动玩法「剧本迷思」和「特遣纪录：故事的魔法」中变得更强，还可以提升完成「剧本迷思」挑战后获得的「飘零的灵感」和同调率奖励。\n\n<Title:成就奖励>\n1、完成成就任务可以获得活动限定头像「以银钥之名：莉莉」、活动货币「飘零的灵感」、银芯。\n2、包含 25 个任务：通关「剧本迷思」的每个关卡 1 次、使用每个界域队伍通关 「剧本迷思」 1/2 次、通关「特遣纪录：故事的魔法」每个调查事件 1 次、完成所有活动成就。\n\n<Title:特遣纪录>\n1、活动期间，「特遣纪录：故事的魔法」可免费解锁。\n2、在「特遣纪录：故事的魔法」中，守密人将使用包含剧情预设「莉莉」的特殊编队进行挑战。\n\n<Title:复刻补偿>\n1、此前已经解锁「特遣纪录：故事的魔法」的守密人，在本次复刻活动期间重新解锁时将会获得「飘零的灵感」×1000的补偿。\n此前已经获得活动限定头像「以银钥之名：莉莉」的守密人，重复获得时将自动转换为「飘零的灵感」×3000。\n此前已经获得激活共鸣材料「演绎之心」的守密人，每获得 1 个多余的「演绎之心」将自动转换为「蔷薇金券」×5000。\n",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 4102448400,
    ActivityEndTime = 4102448400,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_71102_ActivityPlot|朵尔交待的任务，从来都不简单。\n即便她数次提醒大家「要玩得开心」，可首次带着一群唤醒体出门，守密人怎么能不胆战心惊？\n但，要记得「玩得开心」哦。",
