    ActivityPara1 = {35, 57354},
    ActivityPara2 = "58500,58513,58516",
    ActivityName = "Activity_67734_ActivityName|无形交响·复刻",
    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_MapHameln02.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map57.png",
    ActivityTips = "Activity_67734_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「轰鸣之音」和「成就奖励」收集活动货币「高亢乐章」，「高亢乐章」可在「安眠宫殿」中兑换丰厚奖励，包括活动限定SR命轮「永不停歇的演奏」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间，完成「成就奖励」的任务可获得活动限定头像「以银钥之名：哈姆林」、活动限定SR命轮「永不停歇的演奏」、银芯和大量活动货币「高亢乐章」。\n\n<Title:活动时间>\n1、9 月 9 日 9:00 - 9 月 23 日 9:00（GMT+8），所有活动内容均可参与。\n2、9 月 23 日 9:00 - 9 月 30 日 9:00（GMT+8），仅保留「安眠宫殿」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 轰鸣之音>\n1、「轰鸣之音」包含 9 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战不同的关卡除了获得不同的素材掉落外，还将获得活动货币「高亢乐章」。\n3、本次活动关卡为直接战斗的素材关卡，通关后可重现！每次「重现」消耗 「灵啡肽」× 120 。\n4、请注意：使用「重现」功能时，无法获得同调率。\n\n<Title: 乐章加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「轰鸣之音」关卡任务报酬中的「高亢乐章」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「哈姆林」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「永恒安魂曲」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「永不停歇的演奏」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「乐章加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「乐章加成」影响。\n\n<Title: 安眠宫殿>\n1、「安眠宫殿」仅在 9 月 9 日 9:00 - 9 月 30 日 9:00（GMT+8）期间开放。\n2、9 月 30 日 9:00（GMT+8）后，剩余未兑换的「高亢乐章」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。",
    ActivityTimeType = "FixedTime",
    ActivityStartTime = 4102448400,
    ActivityEndTime = 4104262800,
    ActivityStageCondition = 8126,
    ActivityPlot = "Activity_67734_ActivityPlot|交响是编织的艺术，不同器乐的轨迹交织成纵横的图谱。\n在他的织网中，每个音符都将各司其职。\n聆听吧，一支绝伦的交响即刻开演。",
    ActivityDisplay = 2,
    BannerPic = "UIResources/AtlasSource/UI_Main_Image/UI_Main_Activity_16.png",
    BannerText = "Activity_67734_BannerText|玩法活动限时开启！",
    ActivityStageEndTime = 1757293200,
    ActivityStageEndContent = "Activity_67734_ActivityStageEndContent|活动已结束，当前仅可参与「安眠宫殿」"
  },
