    TagPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_MapRyker_small.png",
    ActivityPicture = "UIResources/UIBigImages/UI_Large/UI_Large_Events/UI_Events_Image_Map48.png",
    ActivityTips = "Activity_67732_ActivityTips|<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「月夜传说」和「成就奖励」收集活动货币「决胜筹码」，「决胜筹码」可在「好运俱乐部」中兑换丰厚奖励，包括活动限定SR命轮「命运轮盘赌」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间，完成「成就奖励」的任务可获得活动限定头像「以银钥之名：莱克」、活动限定SR命轮「命运轮盘赌」、银芯和大量活动货币「决胜筹码」。\n3、活动期间，「特遣纪录：狩猎愉快！」将免费开放。\n\n<Title:活动时间>\n1、8 月 12 日 9:00 - 8 月 26 日 9:00（GMT+8），所有活动内容均可参与。\n2、8 月 26 日 9:00 - 9 月 2 日 9:00（GMT+8），仅保留「好运俱乐部」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 月夜传说>\n1、「月夜传说」包含 9 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战不同的关卡除了获得不同的素材掉落外，还将获得活动货币「决胜筹码」。\n3、本次活动关卡为直接战斗的素材关卡，通关后可重现！每次「重现」消耗 「灵啡肽」× 120 。\n4、请注意：使用「重现」功能时，无法获得同调率。\n\n<Title: 筹码加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「月夜传说」关卡任务报酬中的「决胜筹码」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「莱克」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「好运时间」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「命运轮盘赌」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「筹码加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「筹码加成」影响。\n\n<Title: 好运俱乐部>\n1、「好运俱乐部」仅在 8 月 12 日 9:00 - 9 月 2 日 9:00（GMT+8）期间开放。\n2、9 月 2 日 9:00（GMT+8）后，剩余未兑换的「决胜筹码」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。\n\n<Title:特遣纪录>\n1、在「特遣纪录：狩猎愉快！」中，守密人将使用包含剧情预设「莱克」的特殊编队进行挑战。\n2、通关「特遣纪录：狩猎愉快！」可获得全新钥令「钥令：一声枪响」。",
