    ActivityTips = "Activity_23723_ActivityTips|活动规则：\n1、活动期间，调查行动第五章临时关闭，钥令「永世执念」暂时由通关调查行动第四章获得。\n2、活动结束后，调查行动第五章再度开放，钥令「永世执念」仍然需要通关调查行动第五章。\n3、另外，此前已达成的第五章成就奖励、关卡成就奖励、探索奖励、通关奖励都会保留，再度开放时（当前计划为  12 月 27 日），相关已完成进度会尽可能平移保留，无需重复完成。",
